<div class="portal-shell"><?php require __DIR__.'/../includes/sidebar.php';?><main class="portal-main"><header class="portal-page-header"><div><span class="eyebrow">MARKETING</span><h1 class="mt-2 mb-1">Promotions</h1><p class="text-muted mb-0">Create controlled promo codes with minimum spend, dates, and usage limits.</p></div><a class="btn btn-coffee" href="<?=url('admin/promotion-form.php')?>"><i class="bi bi-plus-lg me-2"></i>New promotion</a></header><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><section class="portal-card inventory-filter-card"><form method="get" class="supplier-filter-grid"><div><label class="form-label">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Promo code or name"></div><div><label class="form-label">Status</label><select class="form-select" name="status"><option value="ALL">All</option><option value="ACTIVE" <?=$status==='ACTIVE'?'selected':''?>>Active</option><option value="INACTIVE" <?=$status==='INACTIVE'?'selected':''?>>Inactive</option></select></div><div class="inventory-filter-actions"><button class="btn btn-coffee">Apply</button><a class="btn btn-outline-secondary" href="<?=url('admin/promotions.php')?>">Reset</a></div></form></section><section class="portal-card mt-4"><div class="panel-heading"><div><span class="eyebrow">PROMO CODES</span><h2><?=count($promos)?> promotion<?=count($promos)===1?'':'s'?></h2></div></div><?php if(!$promos):?><div class="empty-state compact"><i class="bi bi-ticket-perforated"></i><h3>No promotions found</h3><p>Create a promo code to offer a controlled discount.</p></div><?php else:?><div class="promo-grid"><?php foreach($promos as $p):?><article class="promo-card <?=$p['status']!=='ACTIVE'?'is-inactive':''?>"><div class="promo-card-top"><div><span class="promo-code"><?=e($p['code'])?></span><h3><?=e($p['name'])?></h3></div><span class="badge <?=$p['status']==='ACTIVE'?'text-bg-success':'text-bg-secondary'?>"><?=e($p['status'])?></span></div><strong class="promo-value"><?=$p['discount_type']==='PERCENT'?e(rtrim(rtrim(number_format((float)$p['discount_value'],2,'.',''),'0'),'.')).'%':money((float)$p['discount_value'])?> OFF</strong><dl><div><dt>Minimum</dt><dd><?=money((float)$p['minimum_spend'])?></dd></div><div><dt>Used</dt><dd><?=(int)$p['usage_count']?><?=!empty($p['usage_limit'])?' / '.(int)$p['usage_limit']:''?></dd></div><div><dt>Customer limit</dt><dd><?=!empty($p['per_customer_limit'])?(int)$p['per_customer_limit']:'Unlimited'?></dd></div><div><dt>Discount given</dt><dd><?=money((float)$p['discount_given'])?></dd></div></dl><small class="text-muted"><?=e(($p['start_date']?:'No start').' → '.($p['end_date']?:'No expiry'))?></small><div class="supplier-actions mt-3"><a class="btn btn-sm btn-outline-coffee" href="<?=url('admin/promotion-form.php?id='.(int)$p['id'])?>">Edit</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="promotion_id" value="<?=(int)$p['id']?>"><button class="btn btn-sm <?=$p['status']==='ACTIVE'?'btn-outline-danger':'btn-outline-success'?>" data-confirm="<?=$p['status']==='ACTIVE'?'Deactivate this promotion?':'Activate this promotion?'?>"><?=$p['status']==='ACTIVE'?'Deactivate':'Activate'?></button></form></div></article><?php endforeach;?></div><?php endif;?></section></main></div><?php require __DIR__.'/../includes/footer.php';?>
